#include "app_config.h"

#if TCFG_RDX_ENABLE && RDX_CFG_OTA_ENABLE

#include <stdint.h>
#include <string.h>

#include "system/includes.h"
#include "spinlock.h"
#include "timer.h"
#include "dual_bank_updata_api.h"
#include "update.h"
#include "update_loader_download.h"
#include "rdx/ports/rdx_firmware_update_port.h"

/*
 * Despite its name, the uncompressed db_update_data.bin generated by
 * CONFIG_DB_UPDATE_DATA_GENERATE_EN is the raw passive dual-bank image.  It
 * does not contain the 0x5c6a7b8e package header required by db_update_*.
 * Keep this path aligned with the BR56 third-party OTA examples and the BR28
 * RDX reference implementation.
 */
extern u8 dual_bank_update_verify_without_crc(
    int (*verify_result_hdl)(int calc_crc));

struct rdx_firmware_update_runtime {
    spinlock_t lock;
    uint8_t initialized;
    uint8_t active;
    uint8_t finishing;
    uint8_t verifying;
    uint8_t committing;
    uint8_t callback_quarantine;
    uint16_t outstanding_writes;
    uint16_t watchdog_id;
    rdx_firmware_update_event_callback_t event_callback;
    void *event_context;
    rdx_firmware_update_timeout_callback_t timeout_callback;
    void *timeout_context;
};

static struct rdx_firmware_update_runtime rdx_firmware_update;

static void rdx_firmware_update_init_once(void)
{
    if (!rdx_firmware_update.initialized) {
        memset(&rdx_firmware_update, 0,
               sizeof(rdx_firmware_update));
        spin_lock_init(&rdx_firmware_update.lock);
        rdx_firmware_update.initialized = 1;
    }
}

static void rdx_firmware_update_emit(
    enum rdx_firmware_update_event_type type, int platform_result)
{
    struct rdx_firmware_update_event event;
    rdx_firmware_update_event_callback_t callback;
    void *context;

    spin_lock(&rdx_firmware_update.lock);
    callback = rdx_firmware_update.event_callback;
    context = rdx_firmware_update.event_context;
    spin_unlock(&rdx_firmware_update.lock);
    if (!callback) {
        return;
    }
    event.type = type;
    event.platform_result = platform_result;
    callback(&event, context);
}

static void rdx_firmware_update_fail(
    enum rdx_firmware_update_event_type type, int platform_result)
{
    uint8_t notify = 0;

    spin_lock(&rdx_firmware_update.lock);
    if (rdx_firmware_update.active) {
        rdx_firmware_update.active = 0;
        rdx_firmware_update.finishing = 0;
        rdx_firmware_update.verifying = 0;
        rdx_firmware_update.committing = 0;
        rdx_firmware_update.callback_quarantine =
            rdx_firmware_update.outstanding_writes != 0;
        notify = 1;
    }
    spin_unlock(&rdx_firmware_update.lock);
    if (!notify) {
        return;
    }
    rdx_firmware_update_watchdog_cancel();
    dual_bank_passive_update_exit(NULL);
    norflash_set_write_protect_en();
    set_ota_status(0);
    rdx_firmware_update_emit(type, platform_result);
}

static int rdx_firmware_update_commit_callback(int err)
{
    printf("[RDX][OTA][PLATFORM] commit=done result=%d\n", err);
    if (err) {
        rdx_firmware_update_fail(
            RDX_FIRMWARE_UPDATE_EVENT_COMMIT_FAILED, err);
        return 0;
    }

    spin_lock(&rdx_firmware_update.lock);
    if (!rdx_firmware_update.active) {
        spin_unlock(&rdx_firmware_update.lock);
        return 0;
    }
    rdx_firmware_update.active = 0;
    rdx_firmware_update.finishing = 0;
    rdx_firmware_update.verifying = 0;
    rdx_firmware_update.committing = 0;
    rdx_firmware_update.callback_quarantine =
        rdx_firmware_update.outstanding_writes != 0;
    spin_unlock(&rdx_firmware_update.lock);
    norflash_set_write_protect_en();
    set_ota_status(0);
    rdx_firmware_update_emit(RDX_FIRMWARE_UPDATE_EVENT_COMMITTED, 0);
    return 0;
}

static int rdx_firmware_update_verify_callback(int verify_result)
{
    uint32_t ret;
    uint8_t active;
    uint8_t start_commit = 0;

    printf("[RDX][OTA][PLATFORM] verify=done result=%d\n",
           verify_result);
    spin_lock(&rdx_firmware_update.lock);
    active = rdx_firmware_update.active
        && rdx_firmware_update.verifying
        && !rdx_firmware_update.committing;
    spin_unlock(&rdx_firmware_update.lock);
    if (!active) {
        return 0;
    }
    if (verify_result) {
        rdx_firmware_update_fail(
            RDX_FIRMWARE_UPDATE_EVENT_VERIFY_FAILED, verify_result);
        return 0;
    }
    rdx_firmware_update_emit(RDX_FIRMWARE_UPDATE_EVENT_VERIFIED, 0);
    spin_lock(&rdx_firmware_update.lock);
    if (rdx_firmware_update.active
        && rdx_firmware_update.verifying
        && !rdx_firmware_update.committing) {
        rdx_firmware_update.committing = 1;
        start_commit = 1;
    }
    spin_unlock(&rdx_firmware_update.lock);
    if (!start_commit) {
        return 0;
    }
    printf("[RDX][OTA][PLATFORM] commit=start mode=raw_bank\n");
    ret = dual_bank_update_burn_boot_info(
        rdx_firmware_update_commit_callback);
    printf("[RDX][OTA][PLATFORM] commit=accepted result=%u\n", ret);
    if (ret) {
        rdx_firmware_update_fail(
            RDX_FIRMWARE_UPDATE_EVENT_COMMIT_FAILED, ret);
    }
    return 0;
}

static int rdx_firmware_update_verify_progress(int verify_result)
{
    (void)verify_result;
    return 0;
}

static void rdx_firmware_update_try_verify(void)
{
    uint8_t start_verify = 0;
    uint8_t ret;

    spin_lock(&rdx_firmware_update.lock);
    if (rdx_firmware_update.active
        && rdx_firmware_update.finishing
        && !rdx_firmware_update.verifying
        && !rdx_firmware_update.outstanding_writes) {
        rdx_firmware_update.verifying = 1;
        start_verify = 1;
    }
    spin_unlock(&rdx_firmware_update.lock);
    if (!start_verify) {
        return;
    }

    printf("[RDX][OTA][PLATFORM] verify=start mode=raw_bank\n");
    ret = dual_bank_update_verify_without_crc(
        rdx_firmware_update_verify_progress);
    rdx_firmware_update_verify_callback(ret);
}

static int rdx_firmware_update_write_callback(void *priv)
{
    int err = (int)(uintptr_t)priv;
    uint8_t active;

    spin_lock(&rdx_firmware_update.lock);
    if (rdx_firmware_update.outstanding_writes) {
        rdx_firmware_update.outstanding_writes--;
    }
    if (!rdx_firmware_update.active
        && !rdx_firmware_update.outstanding_writes) {
        rdx_firmware_update.callback_quarantine = 0;
    }
    active = rdx_firmware_update.active;
    spin_unlock(&rdx_firmware_update.lock);
    if (err) {
        if (active) {
            rdx_firmware_update_fail(
                RDX_FIRMWARE_UPDATE_EVENT_WRITE_FAILED, err);
        }
        return 0;
    }
    if (active) {
        rdx_firmware_update_try_verify();
    }
    return 0;
}

static void rdx_firmware_update_timeout(void *priv)
{
    rdx_firmware_update_timeout_callback_t callback;
    void *context;

    (void)priv;
    spin_lock(&rdx_firmware_update.lock);
    rdx_firmware_update.watchdog_id = 0;
    callback = rdx_firmware_update.timeout_callback;
    context = rdx_firmware_update.timeout_context;
    spin_unlock(&rdx_firmware_update.lock);
    if (callback) {
        callback(context);
    }
}

static void rdx_firmware_update_reset(void *priv)
{
    (void)priv;
    cpu_reset();
}

int rdx_firmware_update_check_structure(void)
{
    rdx_firmware_update_init_once();
    return UPDATE_DUAL_BANK_IS_SUPPORT() ? 0 : -1;
}

enum rdx_firmware_update_result rdx_firmware_update_begin(
    uint32_t image_size,
    rdx_firmware_update_event_callback_t event_callback,
    void *event_context)
{
    uint32_t ret;

    uint8_t callback_pending;

    if (!image_size || !event_callback
        || rdx_firmware_update_check_structure()) {
        return RDX_FIRMWARE_UPDATE_ERR_ARGUMENT;
    }

    spin_lock(&rdx_firmware_update.lock);
    callback_pending = rdx_firmware_update.callback_quarantine
        || rdx_firmware_update.outstanding_writes;
    spin_unlock(&rdx_firmware_update.lock);
    if (callback_pending) {
        printf("[RDX][OTA][PLATFORM] begin_blocked pending_write_callbacks\n");
        return RDX_FIRMWARE_UPDATE_ERR_INIT;
    }

    rdx_firmware_update_abort();
    ret = dual_bank_passive_update_init(0, image_size, 1024, NULL);
    if (ret) {
        dual_bank_passive_update_exit(NULL);
        return RDX_FIRMWARE_UPDATE_ERR_INIT;
    }
    norflash_set_write_protect_remove();
    ret = dual_bank_update_allow_check(image_size);
    if (ret) {
        dual_bank_passive_update_exit(NULL);
        norflash_set_write_protect_en();
        return RDX_FIRMWARE_UPDATE_ERR_NO_SPACE;
    }

    spin_lock(&rdx_firmware_update.lock);
    rdx_firmware_update.active = 1;
    rdx_firmware_update.finishing = 0;
    rdx_firmware_update.verifying = 0;
    rdx_firmware_update.committing = 0;
    rdx_firmware_update.callback_quarantine = 0;
    rdx_firmware_update.outstanding_writes = 0;
    rdx_firmware_update.event_callback = event_callback;
    rdx_firmware_update.event_context = event_context;
    spin_unlock(&rdx_firmware_update.lock);
    set_ota_status(1);
    return RDX_FIRMWARE_UPDATE_OK;
}

enum rdx_firmware_update_result rdx_firmware_update_write(
    const uint8_t *data, uint16_t len)
{
    uint32_t ret;

    if (!data || !len || len > 1024) {
        return RDX_FIRMWARE_UPDATE_ERR_ARGUMENT;
    }
    spin_lock(&rdx_firmware_update.lock);
    if (!rdx_firmware_update.active || rdx_firmware_update.finishing) {
        spin_unlock(&rdx_firmware_update.lock);
        return RDX_FIRMWARE_UPDATE_ERR_WRITE;
    }
    rdx_firmware_update.outstanding_writes++;
    spin_unlock(&rdx_firmware_update.lock);

    ret = dual_bank_update_write((void *)data, len,
                                 rdx_firmware_update_write_callback);
    if (ret) {
        spin_lock(&rdx_firmware_update.lock);
        if (rdx_firmware_update.outstanding_writes) {
            rdx_firmware_update.outstanding_writes--;
        }
        spin_unlock(&rdx_firmware_update.lock);
        rdx_firmware_update_fail(
            RDX_FIRMWARE_UPDATE_EVENT_WRITE_FAILED, ret);
        return RDX_FIRMWARE_UPDATE_ERR_WRITE;
    }
    return RDX_FIRMWARE_UPDATE_OK;
}

enum rdx_firmware_update_result rdx_firmware_update_finish(void)
{
    spin_lock(&rdx_firmware_update.lock);
    if (!rdx_firmware_update.active || rdx_firmware_update.finishing) {
        spin_unlock(&rdx_firmware_update.lock);
        return RDX_FIRMWARE_UPDATE_ERR_VERIFY;
    }
    rdx_firmware_update.finishing = 1;
    spin_unlock(&rdx_firmware_update.lock);
    rdx_firmware_update_try_verify();
    return RDX_FIRMWARE_UPDATE_OK;
}

void rdx_firmware_update_abort(void)
{
    uint8_t was_active;
    uint8_t callbacks_pending;
    uint16_t pending_writes;

    rdx_firmware_update_init_once();
    rdx_firmware_update_watchdog_cancel();
    spin_lock(&rdx_firmware_update.lock);
    was_active = rdx_firmware_update.active;
    rdx_firmware_update.active = 0;
    rdx_firmware_update.finishing = 0;
    rdx_firmware_update.verifying = 0;
    rdx_firmware_update.committing = 0;
    pending_writes = rdx_firmware_update.outstanding_writes;
    callbacks_pending = pending_writes != 0;
    rdx_firmware_update.callback_quarantine = callbacks_pending;
    rdx_firmware_update.event_callback = NULL;
    rdx_firmware_update.event_context = NULL;
    spin_unlock(&rdx_firmware_update.lock);
    if (callbacks_pending) {
        printf("[RDX][OTA][PLATFORM] callback_quarantine writes=%u\n",
               (unsigned int)pending_writes);
    }
    if (was_active) {
        dual_bank_passive_update_exit(NULL);
        norflash_set_write_protect_en();
        set_ota_status(0);
    }
}

int rdx_firmware_update_watchdog_arm(
    rdx_firmware_update_timeout_callback_t callback,
    void *context, uint32_t timeout_ms)
{
    uint16_t timer_id;

    if (!callback || !timeout_ms) {
        return -1;
    }
    rdx_firmware_update_init_once();
    spin_lock(&rdx_firmware_update.lock);
    rdx_firmware_update.timeout_callback = callback;
    rdx_firmware_update.timeout_context = context;
    timer_id = rdx_firmware_update.watchdog_id;
    spin_unlock(&rdx_firmware_update.lock);
    if (timer_id) {
        sys_timer_re_run(timer_id);
        return 0;
    }

    timer_id = sys_timeout_add_2_task(
        NULL, rdx_firmware_update_timeout, timeout_ms, "app_core");
    if (!timer_id) {
        return -1;
    }
    spin_lock(&rdx_firmware_update.lock);
    rdx_firmware_update.watchdog_id = timer_id;
    spin_unlock(&rdx_firmware_update.lock);
    return 0;
}

void rdx_firmware_update_watchdog_cancel(void)
{
    uint16_t timer_id;

    if (!rdx_firmware_update.initialized) {
        return;
    }
    spin_lock(&rdx_firmware_update.lock);
    timer_id = rdx_firmware_update.watchdog_id;
    rdx_firmware_update.watchdog_id = 0;
    rdx_firmware_update.timeout_callback = NULL;
    rdx_firmware_update.timeout_context = NULL;
    spin_unlock(&rdx_firmware_update.lock);
    if (timer_id) {
        sys_timeout_del(timer_id);
    }
}

int rdx_firmware_update_schedule_reset(uint32_t delay_ms)
{
    if (!delay_ms) {
        return -1;
    }
    return sys_timeout_add_2_task(
               NULL, rdx_firmware_update_reset, delay_ms, "app_core")
        ? 0 : -1;
}

void rdx_firmware_update_reset_now(void)
{
    rdx_firmware_update_reset(NULL);
}

#endif /* TCFG_RDX_ENABLE && RDX_CFG_OTA_ENABLE */
